// Writes minimal silent MP3 placeholders into public/audio/ so the <audio>
// elements can load without errors. Replace with real assets when ready.
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const outDir = path.join(root, 'public', 'audio');
await mkdir(outDir, { recursive: true });

// Minimal valid MPEG-1 Layer III silent frame (~26ms of silence at 44.1kHz, 32 kbps mono).
// Generated by concatenating ~40 silent frames so the file decodes cleanly to ~1s of silence.
const FRAME = Buffer.from([
  0xff, 0xfb, 0x10, 0xc4, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
]);

const ID3 = Buffer.from([
  0x49, 0x44, 0x33, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
]);

const files = ['door-clang.mp3', 'flush.mp3', 'ambient.mp3', 'reveal.mp3'];

for (const name of files) {
  const frames = name === 'flush.mp3' ? 150 : name === 'ambient.mp3' ? 400 : 60;
  const data = Buffer.concat([ID3, ...Array(frames).fill(FRAME)]);
  await writeFile(path.join(outDir, name), data);
  console.log(`wrote public/audio/${name} (${data.length} bytes)`);
}
